INSERT INTO "foreign_data" ("id", "flavortext", "language", "multiverseid", "name", "text", "type", "uuid") VALUES (1, '„Es ist der Wille aller, und meine Hand, die ihn ausführt."', 'German', 148411, 'Ausgewählter der Ahnfrau', 'Erstschlag (Diese Kreatur fügt Kampfschaden vor Kreaturen ohne Erstschlag zu.)
INSERT INTO "foreign_data" ("id", "flavortext", "language", "multiverseid", "name", "text", "type", "uuid") VALUES (2, '"La voluntad de todos, realizada por mi mano."', 'Spanish', 150317, 'Elegido de la Antepasada', 'Daña primero. (Esta criatura hace daño de combate antes que las criaturas sin la habilidad de dañar primero.)
INSERT INTO "foreign_data" ("id", "flavortext", "language", "multiverseid", "name", "text", "type", "uuid") VALUES (3, '« La volonté de tous passe par ma main. »', 'French', 149934, 'Élu de l''Ancêtre', 'Initiative (Cette créature inflige des blessures de combat avant les créatures sans l''initiative.)
INSERT INTO "foreign_data" ("id", "flavortext", "language", "multiverseid", "name", "text", "type", "uuid") VALUES (4, '"La volontà di tutti, eseguita per mano mia."', 'Italian', 148794, 'Prescelto dell''Antenata', 'Attacco improvviso (Questa creatura infligge danno da combattimento prima delle creature senza attacco improvviso.)
INSERT INTO "foreign_data" ("id", "flavortext", "language", "multiverseid", "name", "text", "type", "uuid") VALUES (5, 'すべての意思を、この手で成そう。', 'Japanese', 148028, '祖神に選ばれし者', '先制攻撃 （このクリーチャーは先制攻撃を持たないクリーチャーよりも先に戦闘ダメージを与える。）
INSERT INTO "foreign_data" ("id", "flavortext", "language", "multiverseid", "name", "text", "type", "uuid") VALUES (6, '"A vontade de todos pelas minhas mãos realizada."', 'Portuguese (Brazil)', 149551, 'Eleito da Ancestral', 'Iniciativa (Esta criatura causa dano de combate antes de criaturas sem a habilidade de iniciativa.)
INSERT INTO "foreign_data" ("id", "flavortext", "language", "multiverseid", "name", "text", "type", "uuid") VALUES (7, '"Общая воля моей рукой вершится".', 'Russian', 149168, 'Избранник Прародителя', 'Первый удар (Это существо наносит боевые повреждения раньше существ без Первого удара.)
INSERT INTO "foreign_data" ("id", "flavortext", "language", "multiverseid", "name", "text", "type", "uuid") VALUES (8, '「众生所愿，吾手所圆。」', 'Chinese Simplified', 147645, '祖灵的爱民', '先攻（此生物会比不具先攻异能的生物提前造成战斗伤害。）
INSERT INTO "foreign_data" ("id", "flavortext", "language", "multiverseid", "name", "text", "type", "uuid") VALUES (9, 'Jede ihrer Tränen ist ein Tropfen Unsterblichkeit.', 'German', 148412, 'Engel der Gnade', 'Fliegend (Diese Kreatur kann außer von fliegenden Kreaturen und Kreaturen mit Reichweite nicht geblockt werden.)
INSERT INTO "foreign_data" ("id", "flavortext", "language", "multiverseid", "name", "text", "type", "uuid") VALUES (10, 'Cada lágrima derramada es una gota de inmortalidad.', 'Spanish', 150318, 'Ángel de piedad', 'Vuela. (Esta criatura no puede ser bloqueada excepto por criaturas que tengan la habilidad de volar o alcance.)
INSERT INTO "foreign_data" ("id", "flavortext", "language", "multiverseid", "name", "text", "type", "uuid") VALUES (11, 'Chaque larme versée est une goutte d''immortalité.', 'French', 149935, 'Ange de miséricorde', 'Vol (Cette créature ne peut être bloquée que par des créatures avec le vol ou la portée.)
INSERT INTO "foreign_data" ("id", "flavortext", "language", "multiverseid", "name", "text", "type", "uuid") VALUES (12, 'Ogni lacrima versata è una goccia d''immortalità.', 'Italian', 148795, 'Angelo della Misericordia', 'Volare (Questa creatura non può essere bloccata tranne che da creature con volare o raggiungere.)
INSERT INTO "foreign_data" ("id", "flavortext", "language", "multiverseid", "name", "text", "type", "uuid") VALUES (13, '流す涙は不死の滴。', 'Japanese', 148029, '慈悲の天使', '飛行 （このクリーチャーは飛行や到達を持たないクリーチャーによってブロックされない。）
INSERT INTO "foreign_data" ("id", "flavortext", "language", "multiverseid", "name", "text", "type", "uuid") VALUES (14, 'Cada lágrima derramada é uma gota de imortalidade.', 'Portuguese (Brazil)', 149552, 'Anjo de Misericórdia', 'Voar (Esta criatura só pode ser bloqueada por criaturas com a habilidade de voar ou alcance.)
INSERT INTO "foreign_data" ("id", "flavortext", "language", "multiverseid", "name", "text", "type", "uuid") VALUES (15, 'Каждая пролитая слеза это капля бессмертия.', 'Russian', 149169, 'Ангел Милосердия', 'Полет (Это существо может быть заблокировано только существом с Полетом или Захватом.)
INSERT INTO "foreign_data" ("id", "flavortext", "language", "multiverseid", "name", "text", "type", "uuid") VALUES (16, '每颗泪珠都是一滴不朽。', 'Chinese Simplified', 147646, '慈悲天使', '飞行（只有具飞行或延势异能的生物才能阻挡它。）
INSERT INTO "foreign_data" ("id", "flavortext", "language", "multiverseid", "name", "text", "type", "uuid") VALUES (17, '„Als es zur Neuverteilung kam, bat der Adler darum, Mensch werden zu dürfen. Die Ahnfrau gewährte das Gebet zur Hälfte." —Nomadenlegende', 'German', 148424, 'Avior-Wolkenjäger', 'Fliegend (Diese Kreatur kann außer von fliegenden Kreaturen und Kreaturen mit Reichweite nicht geblockt werden.)
INSERT INTO "foreign_data" ("id", "flavortext", "language", "multiverseid", "name", "text", "type", "uuid") VALUES (18, '"En la Nueva Repartición, Águila suplicó ser humano. La Antepasada le concedió la mitad de esa súplica." —Mito nómada', 'Spanish', 150323, 'Cazanubes aven', 'Vuela. (Esta criatura no puede ser bloqueada excepto por criaturas que tengan la habilidad de volar o alcance.)
INSERT INTO "foreign_data" ("id", "flavortext", "language", "multiverseid", "name", "text", "type", "uuid") VALUES (19, '« Lors de la Grande Réattribution, les aigles demandèrent à devenir humains. L''Ancêtre exauça cette prière à moitié. » —Mythe des nomades', 'French', 149940, 'Avemain chasse-nuage', 'Vol (Cette créature ne peut être bloquée que par des créatures avec le vol ou la portée.)
INSERT INTO "foreign_data" ("id", "flavortext", "language", "multiverseid", "name", "text", "type", "uuid") VALUES (20, '"Durante la Ridistribuzione, le Aquile chiesero di diventare umane. Gli Antenati esaudirono solo in parte la loro preghiera." —Mito nomade', 'Italian', 148807, 'Caccianubi Aviano', 'Volare (Questa creatura non può essere bloccata tranne che da creature con volare o raggiungere.)
